"""Render a portable, read-only Boundary Lab report without external assets."""

import json
import math
from collections.abc import Mapping
from pathlib import Path


def _json_value(value):
    """Keep optional diagnostic values serializable and valid browser JSON."""
    if isinstance(value, Mapping):
        return {str(key): _json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_value(item) for item in value]
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if value is None or isinstance(value, (str, bool, int, float)):
        return value
    return str(value)


def render(report: dict, output: Path) -> None:
    """Write one self-contained HTML file; the browser never executes probes."""
    payload = json.dumps(_json_value(report), ensure_ascii=False, allow_nan=False)
    # A script element is HTML raw text even when its type is application/json.
    # Escape markup delimiters rather than trusting JSON's string quoting.
    for character, escaped in (
        ("&", "\\u0026"),
        ("<", "\\u003c"),
        (">", "\\u003e"),
        ("\u2028", "\\u2028"),
        ("\u2029", "\\u2029"),
    ):
        payload = payload.replace(character, escaped)
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(_PAGE.replace("__REPORT_JSON__", payload), encoding="utf-8")


